import unittest
from bottle_utils import html_escape

class GeneratedSeedTests(unittest.TestCase):
    def test_seed(self):
        result = html_escape("")
        self.assertEqual(result, "")

    def test_special_characters(self):
        result = html_escape("&<>")
        self.assertEqual(result, "&amp;&lt;&gt;")
